use itertools::izip;
use proconio::input;
use std::cmp::Reverse;

fn main() {
    input!(
        n: usize,
        x: usize,
        y: usize,
        z: usize,
        a: [u32; n],
        b: [u32; n]
    );

    let mut s = izip!(1.., a, b).collect::<Vec<_>>();
    s.sort_by_key(|&(i, a, _b)| (Reverse(a), i));
    s[x..].sort_by_key(|&(i, _a, b)| (Reverse(b), i));
    s[x + y..].sort_by_key(|&(i, a, b)| (Reverse(a + b), i));
    s[..x + y + z].sort_by_key(|&(i, ..)| i);

    for &(i, ..) in &s[..x + y + z] {
        println!("{}", i);
    }
}

